Let $\mathbf{q}_k \triangleq \mathbf{GA}_{k}^{-1} \mathbf{Z} \mathbf{p_t}$. Using $\mathbf{G}^T=\mathbf{G}^{-1} = \mathbf{G}$, $\mathbf{GA}_{i}^{-1}\mathbf{G}= \mathbf{A}_i^{-T}$ and $ \mathbf{GA}_{k}\mathbf{G} = \mathbf{A}_k^{T}$ we get
\begin{equation}
  \D J(k) = \mathbf{q}_k^T \Big( \mathbf{A}_{k}^{-1} - \mathbf{A}_{k}^{-1} \mathbf{Z} \sum_{i=k_1}^{k_{ol}} \mathbf{A}_{i}^{-1}\mathbf{A}_{i}^{-T}\mathbf{A}_{k}^T  \Big) \mathbf{q}_k
\end{equation}
Let $\mathbf{M}_k = \sum_{i=k_1}^{k_{ol}}\mathbf{A}_{i}^{-1}\mathbf{A}_{i}^{-T}\mathbf{A}_{k}^T$ and $\mathbf{Q}_k =  \mathbf{A}_{k}^{-1} - \mathbf{A}_{k}^{-1} \mathbf{Z} \mathbf{M}_k $. When $n_{ol} = o(N)$ (i.e., when $\lim_{N \rightarrow \infty} \frac{n_{ol}}{N} = 0$), we have the total number of frequencies, $n_1+n_2 = O(N)$. Since $\mathbf{A}_i^{-1} \mathbf{A}_i^{-T} \mathbf{A}^T_k = O(1)$ for each $i$ and $k$, we have $\mathbf{M}_k = O(n_{ol})$ and $\mathbf{Z} = O(1/N)$. Thus,
\begin{equation}\label{eqn}
\begin{aligned}
   \lim_{N \rightarrow \infty} \mathbf{A}_{k}^{-1} \mathbf{ZM}_k &= \mathbf{0} \\
   \Rightarrow \ \lim_{N \rightarrow \infty} \mathbf{Q}_k + \mathbf{Q}_k^T &= \mathbf{A}_{k}^{-1}+\mathbf{A}_{k}^{-T} \succ \mathbf{0}
\end{aligned}
\end{equation}
from Theorem~\ref{thrm:B_existNE}. Thus we get $\mathbf{x}^T\mathbf{Q}_k\mathbf{x} > 0 \ \forall \mathbf{x} \in \mathbb{R}^{2 \times 1}$ as its symmetric part $\mathbf{Q}_k + \mathbf{Q}_k^T$ is positive definite \cite{johnson1970positive}. Hence, we get $\D J(k) \geq 0$ when $N \rightarrow \infty$, with equality when $J(k)=0$.
\qed

