it follows from \eqref{3.63} and \eqref{4.8} that 
\begin{align}
\left|J_8^{n+1}-J^{n}_8\right|&\leq C\r^{2\b-1}\int_{\Pi_{j=1}^{k-1}\mathcal{V}_j} \Fi_{\{t_k>0\}}|(\hat{h}^{n+2}-\hat{h}^{n+1})(t_k,x_k,v_{k-1})|\,\dd\hat\Sigma_{k-1}^n(t_k)\nonumber\\
&\quad+C\r^{2\b-1}\f{|I^{n+1}(t,t_1)-I^n(t,t_1)|}{1+|v|}\sup_{0\leq\tau\leq t}\|\hat{h}^{n+2}(\tau)\|_{L^\infty}\int_{\Pi_{j=1}^{k-1}\mathcal{V}_j} \Fi_{\{t_k>0\}}\,\dd\hat\Sigma_{k-1}^{n+1}(t_k)\nonumber\\
&\quad+C\r^{2\b-1}\sup_{0\leq\tau\leq t}\|\hat{h}^{n+1}(\tau)\|_{L^\infty}\left|\int_{\Pi_{j=1}^{k-1}\mathcal{V}_j} \Fi_{\{t_k>0\}}\left\{\dd\hat\Sigma_{k-1}^{n+1}(t_k)-\dd\hat\Sigma_{k-1}^{n}(t_k)\right\}\right|,\nonumber 
%&\leq C\r^{2\b}\left(\f12\right)^{C_2\r^{\f54}} \sup_{0\leq\tau\leq t}\|(\hat{h}^{n+2}-\hat{h}^{n+1})(\tau)\|_{L^\infty}\nonumber\\
%&\qquad\qquad\qquad+C_{\r}t \|h_0\|_{L^\infty}\sup_{0\leq\tau\leq t}\|(\hat{h}^{n+1}-\hat{h}^{n})(\tau)\|_{L^\infty}.
\end{align}
and hence
\begin{equation}
\label{3.66}
\left|J_8^{n+1}-J^{n}_8\right|\leq C\r^{2\b}\left(\f12\right)^{C_2\r^{\f54}} \sup_{0\leq\tau\leq t}\|(\hat{h}^{n+2}-\hat{h}^{n+1})(\tau)\|_{L^\infty} %\\
+C_{\r}t \|h_0\|_{L^\infty}\sup_{0\leq\tau\leq t}\|(\hat{h}^{n+1}-\hat{h}^{n})(\tau)\|_{L^\infty}.
\end{equation}
Now, by substituting \eqref{3.58}, \eqref{3.64}, \eqref{3.65} and \eqref{3.66} into \eqref{3.56}, and then combining \eqref{3.53}, one obtains that 
\begin{multline}\label{3.67}
\|(\hat{h}^{n+1}-\hat{h}^{n})(t)\|_{L^\infty}
\leq C_5\r^{2\b}\left(\f12\right)^{C_2\r^{\f54}} \sup_{0\leq\tau\leq t}\|(\hat{h}^{n+2}-\hat{h}^{n+1})(\tau)\|_{L^\infty}\\
+C_{\r}t \left(1+\|h_0\|_{L^\infty}\right)\sup_{0\leq\tau\leq t}\|(\hat{h}^{n+1}-\hat{h}^{n})(\tau)\|_{L^\infty},
\end{multline}
where $C_5\geq1$ is a positive constant.
As before, we let $\r>0$ be fixed suitably large such that 
\begin{equation}%\label{ }
C_5\r^{2\b}\left(\f12\right)^{C_2\r^{\f54}} \leq \f12.\nonumber
\end{equation}

