\noindent{\bf Step 2.} We claim that the integrand in \eqref{eq:vd-V-formula} has the following bound: $\forall s\in(0,t)$,
\begin{equation}
\label{eq:uniform-bd}
\Abs{V_\omega(t-s,y)\sum_{i=1}^d(\vd{y}\omega)(y,y+e_i)\nabla_i^2 p_s^{\omega_y'}(y,0)}
\lesssim
(\tx_y\tx_y')^{d-1}(1+s)^{-\gamma-0.5d}.
\end{equation}
Indeed,  by \eqref{eq:heat-eq-u} and applying the Harnack inequality (Corollary~\ref{acor:Kry-Saf}) for the operator $(\partial_t-L_\omega)$ in a similar manner as in \eqref{eq:osc-v-tilde},  we have
\begin{align*}
&\Abs{V_\omega(t-s,y)\sum_{i=1}^d(\vd{y}\omega)(y,y+e_i)\nabla_i^2 p_s^{\omega_y'}(y,0)}\\
&\stackrel{\eqref{eq:V-bound}}\lesssim 
\tx_y^{d-1}
\osc_{\bar B_1(y)}p_s^{\omega_y'}(\cdot,0)
\lesssim 
\tx_y^{d-1}
s^{-\gamma}p_{2s}^{\omega_y'}(y,0)
\end{align*}
for $s>1$.  Hence \eqref{eq:uniform-bd} follows from Theorem~\ref{thm:hk-bounds} when $s>1$.
When $s\le 1$,  \eqref{eq:uniform-bd} is a trivial consequence of \eqref{eq:V-bound} since $\abs{\nabla_i^2 p_s^{\omega_y'}(y,0)}\le 2$.  Display \eqref{eq:uniform-bd} is proved.

